# --------------------------------------------------------------------- FEEDL
# Absolute positioning target in 1/7200 in from home (tables.py's
# convention). FEEDL_FRAME1 is trace 04's captured frame-1 value (the
# dpi captures have no positioning move -- see the module docstring);
# FEEDL_PITCH (38.0 mm) is tables.FEEDL_PITCH.
FEEDL_FRAME1 = 6746
FEEDL_PITCH = 10760


def feedl_for_frame(frame: int) -> int:
    """Absolute FEEDL target for `frame` (1-based), from home."""
    return FEEDL_FRAME1 + (frame - 1) * FEEDL_PITCH

